    {
      "id": "W7204075121",
      "doi": "10.1007/s12559-026-10619-1",
      "title": "From Language Models to Agentic AI: A Survey of Autonomous, Action-Enabled, and Collaborative LLM Agents",
      "year": 2026,
      "type": "article",
      "venue": {
        "name": "Cognitive Computation",
        "issn": "1866-9956"
      },
      "authors": [
        "Sparsh Bajoria -",
        "Sumit Ranjan",
        "Adhitya M"
